sectors=[('dakwerken','Dakwerken','/dakwerken/','/dakwerken-info/','/assets/dak-hellend.jpg','Een dak herstellen of vernieuwen: materialen, isolatie en budget.'),('zonnepanelen','Zonnepanelen','/zonnepanelen/','/zonnepanelen-info/','/zonnepanelen/assets/solar-home.png','Van een geschikt dak tot een installatie die past bij je verbruik.'),('thuisbatterij','Thuisbatterijen','/thuisbatterij/','/thuisbatterij-info/','/thuisbatterij/assets/battery-home.png','Stroom opslaan, capaciteit kiezen en je mogelijke besparing begrijpen.')]
