head='''<!doctype html><html lang="nl-BE"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{title} | Mijnenergie.be — demo</title><link rel="stylesheet" href="/dakwerken-info/style.css"><link rel="stylesheet" href="/demo/style.css"></head><body><div class="concept">Concept voor DPG · Lokale demo · Geen officiële publicatie</div><header><div class="container header-top"><a href="/demo/"><img class="logo" src="/assets/mijnenergie-logo.png" alt="Mijnenergie.be"></a><a href="/demo/">Demo-overzicht</a></div></header>'''
footer='<footer><div class="container footer-bottom"><span>Concept voor DPG · 2026</span><a href="/demo/">Terug naar het overzicht</a><a href="/blog/">Alle blogs</a></div></footer></body></html>'
(ROOT/'demo').mkdir(exist_ok=True)
rows=''.join(f'''<section class="topic" aria-labelledby="{slug}"><img src="{image}" alt="{label}" width="600" height="400"><div><h2 id="{slug}">{label}</h2><p>{desc}</p><div class="page-links"><a href="{info}"><strong>Informatiepagina <span aria-hidden="true">→</span></strong><span>Uitleg, keuzes en aandachtspunten</span></a><a href="{sales}"><strong>Salespagina <span aria-hidden="true">→</span></strong><span>Richtprijs berekenen met de calculator</span></a><a href="/blog/{slug}/"><strong>10 blogs <span aria-hidden="true">→</span></strong><span>5 korte gidsen en 5 verdiepende artikels</span></a></div></div></section>''' for slug,label,sales,info,image,desc in sectors)
(ROOT/'demo/index.html').write_text(head.format(title='Duurzaam wonen — demo-overzicht')+'''<main id="main" class="container demo-main"><h1>Duurzaam wonen</h1><p class="demo-lead">Bekijk de voorgestelde pagina’s voor Mijnenergie.be. Kies een onderwerp en ontdek de informatiepagina, de calculatorpagina en de bijhorende blogs.</p><div class="legend"><p><strong>Informatiepagina</strong><br>Informeren en gevonden worden via zoekmachines.</p><p><strong>Salespagina</strong><br>Bezoekers naar de calculator begeleiden.</p><p><strong>Blogs</strong><br>Concrete vragen beantwoorden en verder helpen.</p></div>'''+rows+'<p class="all-blogs"><a href="/blog/">Bekijk alle 30 blogs →</a></p></main>'+footer)
content={
'zonnepanelen': {
'title':'Zonnepanelen: werking, installatie en keuzes voor jouw woning',
'lead':'Met zonnepanelen wek je zelf elektriciteit op. Of een installatie bij jouw woning past, hangt af van je dak, je stroomverbruik en de manier waarop je de opgewekte energie gebruikt. Deze gids helpt je de belangrijkste keuzes te begrijpen voordat je een offerte vergelijkt.',
'sections':[
('werking','Hoe werken zonnepanelen?','Zonnepanelen zetten zonlicht om in elektriciteit. De omvormer maakt die stroom bruikbaar voor je woning. Wat je op dat moment verbruikt, gebruik je rechtstreeks; een overschot gaat naar het elektriciteitsnet of kan met een geschikte thuisbatterij worden opgeslagen.','De productie wisselt met het weer, het seizoen en het moment van de dag. Een installatie die op jaarbasis veel produceert, dekt daardoor niet automatisch je verbruik op elk moment. Kijk bij je keuze zowel naar de verwachte productie als naar je dagelijkse verbruiksprofiel.'),
('dak','Is jouw dak geschikt?','Laat de toestand en draagkracht van het dak beoordelen. Oriëntatie, helling, beschikbare ruimte en schaduw beïnvloeden het legplan. Bij een plat dak zijn ook de afstand tussen rijen, afwatering en toegang voor onderhoud belangrijk.','Staat een dakrenovatie op de planning? Stem die af op de plaatsing van de panelen. Je voorkomt daarmee dat een nieuwe installatie kort na de plaatsing opnieuw verwijderd moet worden. Een legplan moet bovendien rekening houden met dakramen, schoorstenen en andere obstakels.'),
('vermogen','Hoeveel panelen heb je nodig?','Begin bij je gemeten elektriciteitsverbruik en de momenten waarop je stroom gebruikt. Een warmtepomp, elektrische wagen of andere geplande verandering kan het toekomstbeeld beïnvloeden. Maak onderscheid tussen je huidige behoefte en plannen die nog niet vaststaan.','Vergelijk het totale installatievermogen in kWp en de verwachte jaarlijkse productie in kWh. Dat zijn verschillende grootheden. Meer panelen kunnen meer produceren, maar de financiële waarde van extra stroom hangt mede af van hoeveel je zelf gebruikt en hoeveel je injecteert.'),
('omvormer','Welke omvormer past bij de installatie?','De omvormer moet passen bij het vermogen, de configuratie en de elektrische aansluiting. Laat uitleggen hoe de voorgestelde oplossing met schaduw omgaat en welke monitoring beschikbaar is. Vergelijk ook de garantie en de ondersteuning na plaatsing.','Wil je later een batterij toevoegen? Vraag welke onderdelen daarvoor al geschikt zijn en welke aanpassingen alsnog nodig kunnen zijn. De omschrijving “batterijklaar” is op zichzelf onvoldoende: laat de compatibiliteit met concrete systemen en functies verduidelijken.'),
('kosten','Wat bepaalt de prijs en besparing?','De offerte kan panelen, omvormer, montagesysteem, bekabeling, plaatsing en keuring bevatten. Vraag expliciet welke werkzaamheden aan het dak of de elektriciteitskast inbegrepen zijn. Een totaalprijs is pas vergelijkbaar wanneer de werkomschrijving gelijk is.','Een besparingsberekening steunt op aannames over productie, eigen gebruik, aankoopprijzen en de vergoeding voor geïnjecteerde stroom. Vraag die aannames op en bekijk meerdere scenario’s. Een berekende terugverdientijd is een inschatting, geen gegarandeerde uitkomst.'),
('verloop','Van dakinspectie tot oplevering','Bespreek eerst je dak, verbruik en verwachtingen. Daarna volgt een legplan met een concrete offerte. Leg vast wie instaat voor de elektrische aanpassingen, keuring en de nodige registratie. Volg voor de actuele procedure de informatie van je netbeheerder.','Vraag bij oplevering het legplan, de productgegevens, keuringsdocumenten en garantievoorwaarden. Controleer de toegang tot de monitoring en noteer bij wie je terechtkunt als de opbrengst afwijkt of een storing optreedt.'),
('gebruik','Meer van je zonnestroom zelf gebruiken','Toestellen laten draaien wanneer de panelen produceren kan helpen om meer van je eigen stroom te gebruiken. Dat hangt af van de toestellen en van wat praktisch mogelijk is in jouw huishouden. Gebruik gemeten data om te zien hoeveel ruimte er voor verbetering is.','Een thuisbatterij is een mogelijke aanvulling, maar vraagt een afzonderlijke afweging van investering, capaciteit en sturing. Laat de variant zonder batterij en die met batterij apart berekenen. Zo zie je welk voordeel aan de panelen en welk voordeel aan de batterij wordt toegeschreven.')],
'faq':[('Kunnen zonnepanelen ook op een plat dak?','Dat kan bij een geschikte constructie en een passend montagesysteem. Laat onder meer draagkracht, windbelasting, afwatering en bereikbaarheid beoordelen.'),('Betekent een hoge jaaropbrengst dat ik geen stroom meer moet aankopen?','Nee. Productie en verbruik vallen niet altijd samen. Je kunt op sommige momenten stroom injecteren en op andere momenten stroom aankopen.'),('Moet ik meteen een thuisbatterij nemen?','Dat is een aparte keuze. Beoordeel eerst je verbruiksprofiel en laat de kosten en mogelijke voordelen van de batterij afzonderlijk onderbouwen.')],
'sources':[('Fluvius: zonnepanelen en wijzigingen','https://www.fluvius.be/nl/groene-energie/zonnepanelen-melden/wijzigingen-zonnepanelen')]
},
'thuisbatterij':{
'title':'Thuisbatterij: werking, capaciteit en aandachtspunten',
'lead':'Een thuisbatterij bewaart elektriciteit om die op een later moment te gebruiken. Of dat voor jouw woning interessant is, hangt af van je verbruik, de aanwezige zonnepanelen, de sturing en de volledige investering. Deze gids helpt je de juiste vragen te stellen.',
'sections':[
('werking','Wat doet een thuisbatterij?','Een thuisbatterij kan een deel van de elektriciteit opslaan die je op dat moment niet gebruikt. Later levert ze die stroom weer aan je woning. In combinatie met zonnepanelen kan dat helpen om productie van overdag naar de avond te verschuiven.','Opslag brengt verliezen met zich mee. De stroom die wordt geladen, komt dus niet volledig weer beschikbaar. Ook de beschikbare capaciteit en het laadvermogen begrenzen wat het systeem op een bepaald moment kan doen.'),
('capaciteit','Welke batterijcapaciteit past bij jouw woning?','De capaciteit in kWh vertelt hoeveel energie de batterij kan opslaan. Vraag naar de bruikbare capaciteit en de voorwaarden waaronder die geldt. Een groot systeem is niet vanzelf de beste keuze: het moet regelmatig zinvol kunnen laden en ontladen.','Laat je werkelijke productie en verbruik als uitgangspunt gebruiken. Dag- of kwartiergegevens kunnen meer vertellen dan alleen een jaartotaal. Vraag bij meerdere capaciteiten welk verschil in benutting en verwachte besparing de aanbieder berekent.'),
('vermogen','Capaciteit en vermogen zijn verschillende dingen','Het vermogen in kW bepaalt hoe snel de batterij kan laden of energie leveren. Een batterij kan voldoende opgeslagen energie hebben en toch onvoldoende vermogen om verschillende zware toestellen tegelijk te ondersteunen.','Bespreek de elektrische aansluiting, het aantal fasen en de combinatie met de omvormer. Laat aangeven welke toestellen de batterij kan ondersteunen en wanneer de woning nog stroom van het net nodig heeft. Beoordeel capaciteit en vermogen dus samen.'),
('bestaande','Een batterij bij bestaande zonnepanelen','Bij een bestaande installatie moet de installateur nagaan hoe de batterij kan worden aangesloten. Dat kan aanpassingen aan de omvormer, bekabeling of elektriciteitskast vragen. Vraag welke bestaande onderdelen behouden blijven.','Vergelijk een uitbreiding en een voorstel waarbij ook andere onderdelen worden vervangen. Laat de kosten uitsplitsen en vraag wat de wijziging betekent voor monitoring, garanties, keuring en registratie. Compatibiliteit moet voor het concrete systeem worden bevestigd.'),
('sturing','Wat doet slimme sturing?','Sturing bepaalt wanneer de batterij laadt en ontlaadt. Een systeem kan bijvoorbeeld reageren op zonneproductie, je verbruik of tariefinformatie. De bruikbare functies hangen af van de apparatuur, software en het energiecontract.','Vraag of de functies een abonnement vereisen, welke terugkerende kosten gelden en wat gebeurt als je van energieleverancier verandert. Bespreek ook welke werking overblijft zonder internetverbinding en wie toegang heeft tot instellingen en gegevens.'),
('kosten','Hoe beoordeel je kosten en mogelijke besparing?','Vergelijk de volledige investering: batterij, omvormer of aanpassingen, plaatsing, elektrische werken en eventuele softwarekosten. Vraag welke prestaties en garanties concreet zijn opgenomen en welke onderdelen afzonderlijke voorwaarden hebben.','De besparing hangt samen met het gebruik van de batterij en de waarde van de verplaatste stroom. Vraag naar de aannames en naar een minder gunstig scenario. Trek terugkerende kosten mee af. Een voorspelde opbrengst is geen vaste jaarlijkse inkomstenstroom.'),
('noodstroom','Werkt de batterij bij een stroomuitval?','Een thuisbatterij levert niet automatisch noodstroom. Daarvoor moeten het systeem en de elektrische installatie de juiste functies en voorzieningen hebben. Vraag welke kringen ondersteund worden en hoe de omschakeling werkt.','Laat een beloofde noodstroomfunctie bij oplevering demonstreren. Bespreek ook beperkingen zoals maximaal vermogen, beschikbare reserve en de mogelijkheid om tijdens de storing met zonnepanelen bij te laden. Die eigenschappen verschillen per systeem.'),
('garantie','Garantie, plaatsing en onderhoud','Vraag naar garantie op de batterij én op de overige onderdelen. Kijk behalve naar het aantal jaren ook naar eventuele voorwaarden over gebruik, capaciteit, registratie en onderhoud. Maak duidelijk wie een defect onderzoekt en welke kosten inbegrepen zijn.','Een installateur bepaalt een geschikte plaats volgens de productvoorschriften en de situatie in de woning. Laat uitleggen welke toegang, omgeving en bescherming nodig zijn. Bewaar bij oplevering de documentatie, instellingen en contactgegevens voor ondersteuning.')],
'faq':[('Is een thuisbatterij altijd rendabel?','Nee. Dat hangt af van de investering, het verbruiksprofiel, de tarieven, de benutting en eventuele terugkerende kosten. Laat de aannames van de berekening uitleggen.'),('Kan een batterij mijn woning volledig onafhankelijk maken?','Niet automatisch. De beschikbare energie en het vermogen zijn begrensd, en zonneproductie wisselt sterk doorheen het jaar.'),('Is noodstroom standaard inbegrepen?','Nee. Vraag expliciet welke noodstroomfunctie wordt voorzien en laat die bij oplevering testen.')],
'sources':[('SMA: batterij en productvoorwaarden','https://www.sma.de/en/products/solar-batteries/sma-home-storage'),('SMA: systeemspecifieke noodstroomwerking','https://manuals.sma.de/STPxx3SE40/en-US/14463271435.html')]
}}
for slug,label,sales,info,image,desc in sectors[1:]:
 d=content[slug];p=ROOT/info.strip('/');p.mkdir(exist_ok=True)
 sections=''.join(f'<section id="{id}"><h2>{title}</h2><p>{a}</p><p>{b}</p></section>' for id,title,a,b in d['sections'])
 toc=''.join(f'<li><a href="#{id}">{title}</a></li>' for id,title,*_ in d['sections'])
 calc=f'https://{slug}.testinstallateur.be/'
 faqs=''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in d['faq'])
 sources=' · '.join(f'<a href="{url}" target="_blank" rel="noopener">{title}</a>' for title,url in d['sources'])
 p.joinpath('index.html').write_text(head.format(title=d['title'])+f'''<main id="main"><div class="container article-heading"><p class="breadcrumb"><a href="/demo/">Demo-overzicht</a> / {label} / Informatie</p><h1>{d['title']}</h1><p class="article-lead">{d['lead']}</p><p class="byline">Informatieve conceptgids · 13 oktober 2026</p></div><div class="container article-layout"><aside class="contents"><h2>Op deze pagina</h2><ol>{toc}<li><a href="#calculator">Bereken jouw situatie</a></li><li><a href="#vragen">Veelgestelde vragen</a></li></ol></aside><article class="guide"><img class="article-photo" src="{image}" alt="{label} bij een woning">{sections}<section id="calculator" class="article-calculator"><h2>Bereken een eerste indicatie voor jouw woning</h2><p>Vul de calculator in om jouw situatie te verkennen. De berekening helpt je bij de voorbereiding van een gesprek met een installateur.</p><iframe title="{label} calculator" src="{calc}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe><p class="small">Indicatieve berekening, geen definitieve offerte of gegarandeerde besparing.</p><a class="text-link" href="{calc}" target="_blank" rel="noopener">Open de calculator in een apart tabblad ↗</a></section><section id="vragen"><h2>Veelgestelde vragen</h2>{faqs}</section><section class="related"><h2>Verder lezen</h2><a href="/blog/{slug}/">Bekijk de tien blogs over {label.lower()}</a><a href="{sales}">Naar de salespagina met calculator</a><p class="small">Aanvullende product- en procedureinformatie: {sources}. Productinformatie geldt voor het beschreven systeem; laat de eigenschappen van jouw voorstel bevestigen.</p></section></article></div></main>'''+footer)
# Shared, independently styled demo navigation on every presentation page.
for p in ROOT.rglob('*.html'):
 if 'research' in p.parts:continue
 s=p.read_text()
 if '/demo/navigation.js' not in s:s=s.replace('</body>','<script src="/demo/navigation.js" defer></script></body>')
 p.write_text(s)
print('Demo-overzicht, twee informatiepagina’s en gedeelde navigatie gemaakt.')
